sub answer_key {
    my ($input) = @_;
    my ($id) = $input =~ /^\[task ([A-Za-z0-9._-]+)\]/m;
    my $files = $ANSWERS->{$id // ''} or return 'I cannot do this task.';
    write_file({path => $_, content => $files->{$_}}) for sort keys %$files;
    return 'done';
}

